void sobel(const uint8_t *input, uint8_t *output, int width, int height)
{
  /* Knob Variables Declaration Start */
  float loop_perforation_factor = 1.0;  // Range: 0.1 to 1.0, Real
  int quantize_enabled = 0;             // 0 = no quantization, 1 = enable quantization, Integer
  int shift_bits = 0;                   // Range: 0 to 4, Integer
  int early_exit_threshold = 255;       // Range: 0 to 255, Integer
  /* Knob Variables Declaration End */

  int perforated_height = height * loop_perforation_factor;
  int perforated_width = width * loop_perforation_factor;

  for (int y = 0; y < perforated_height; y++) {
    for (int x = 0; x < perforated_width; x++) {

      if (x == 0 || x == width - 1 || y == 0 || y == height - 1) {
        output[y * width + x] = 0;
        continue;
      }

      /* Apply 4-Bit Quantization */
      int p00 = quantize_enabled ? (input[(y-1)*width + (x-1)] >> shift_bits) : input[(y-1)*width + (x-1)];
      int p01 = quantize_enabled ? (input[(y-1)*width +  x   ] >> shift_bits) : input[(y-1)*width +  x   ];
      int p02 = quantize_enabled ? (input[(y-1)*width + (x+1)] >> shift_bits) : input[(y-1)*width + (x+1)];
      int p10 = quantize_enabled ? (input[ y   *width + (x-1)] >> shift_bits) : input[ y   *width + (x-1)];
      int p12 = quantize_enabled ? (input[ y   *width + (x+1)] >> shift_bits) : input[ y   *width + (x+1)];
      int p20 = quantize_enabled ? (input[(y+1)*width + (x-1)] >> shift_bits) : input[(y+1)*width + (x-1)];
      int p21 = quantize_enabled ? (input[(y+1)*width +  x   ] >> shift_bits) : input[(y+1)*width +  x   ];
      int p22 = quantize_enabled ? (input[(y+1)*width + (x+1)] >> shift_bits) : input[(y+1)*width + (x+1)];

      int gx = -p00 + p02 - 2*p10 + 2*p12 - p20 + p22;
      int gy =  p00 + 2*p01 + p02 - p20 - 2*p21 - p22;

      int mag = abs(gx) + abs(gy);

      /* Apply Early-Exit Approximation */
      if (early_exit_threshold < 255 && mag > early_exit_threshold) {
        mag = 255;
      }

      if (mag > 255) mag = 255;

      output[y * width + x] = (uint8_t)mag;
    }
  }
}
